  failures?: Array<{ code: string; details?: { [key: string]: unknown; }; message: string; node?: { path: string; scene: string; }; phase: string; recovery?: { arguments: { [key: string]: unknown; }; prerequisite?: string; tool: string; }; resource?: string; uri?: string; [key: string]: unknown; }>;
  operation_id: string;
  pending?: Array<string>;
  pending_save?: Array<string>;
  phase?: string;
  phases?: { [key: string]: string; };
  project?: string;
  result_query_error?: { code: string; message: string; };
  resumable?: boolean;
  runtime?: {
  // File identity never proves behavior; assess the requested runtime observation separately.
  behavior: "unverified";
  changed_uris?: Array<string>;
  evidence?: string;
  launch_changed_uris?: Array<string>;
  restart_required?: boolean;
  run_id: string;
  running: boolean;
  scope: string;
  source_snapshot_id?: string;
  startup_changed_uris?: Array<string>;
  startup_files: "unverified" | "matched" | "mismatched" | "unavailable";
  state: "not_running" | "unverified" | "matches_startup" | "source_changed";
