  status: "pending" | "completed" | "partial" | "failed";
  undo?: { edit_id?: string | null; retained_files?: Array<string>; scope?: Array<string>; steps?: Array<{ edit_id: string; scope: string; }>; };
  validation_snapshot?: string;
} | { error: { code: string; details: { [key: string]: unknown; }; message: string; [key: string]: unknown; }; [key: string]: unknown; } | { attachments: Array<{ script?: { node: { path: string; scene: string; }; uri: string; }; shader?: {
